INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('switch over', '切換；轉換到', 'to change from one system or activity to another', '[{"en":"We switched over to the cloud-based system last year.","zh-TW":"我們去年切換到了雲端系統。"},{"en":"It takes time to switch over from the old process.","zh-TW":"從舊流程轉換需要時間。"}]', 'phrasal verb'),
('target toward', '針對；以…為目標', 'to aim an effort or product at a specific group or goal', '[{"en":"The campaign is targeted toward young professionals.","zh-TW":"這次活動針對年輕專業人士。"},{"en":"We target our services toward mid-size enterprises.","zh-TW":"我們的服務以中型企業為目標。"}]', 'phrasal verb'),
('think ahead', '預先考慮；未雨綢繆', 'to consider future needs or plan in advance', '[{"en":"We need to think ahead and anticipate market shifts.","zh-TW":"我們需要預先考慮並預測市場轉變。"},{"en":"Good leaders always think ahead.","zh-TW":"好的領導者總是未雨綢繆。"}]', 'phrasal verb'),
('transition to', '過渡到；轉型至', 'to move gradually from one state or role to another', '[{"en":"She transitioned to a management position this year.","zh-TW":"她今年過渡到了管理職位。"},{"en":"The company is transitioning to a subscription model.","zh-TW":"公司正在轉型至訂閱模式。"}]', 'phrasal verb'),
('turn to', '求助於；轉向', 'to go to someone for help or to change to an alternative', '[{"en":"When issues arise she turns to her mentor.","zh-TW":"當出現問題時她向導師求助。"},{"en":"The company turned to outsourcing to reduce costs.","zh-TW":"公司轉向外包以降低成本。"}]', 'phrasal verb'),
('update on', '更新；告知最新情況', 'to provide the latest information about something', '[{"en":"Please update me on the project status.","zh-TW":"請告知我專案的最新狀態。"},{"en":"She updated the team on the client''s requirements.","zh-TW":"她向團隊通報了客戶的最新需求。"}]', 'phrasal verb'),
('veer away from', '偏離；避開', 'to change direction away from something', '[{"en":"The discussion veered away from the agenda.","zh-TW":"討論偏離了議程。"},{"en":"She veered away from the risky option.","zh-TW":"她避開了風險較高的選項。"}]', 'phrasal verb'),
('validate against', '與…進行驗證；核對', 'to confirm accuracy by checking against a standard', '[{"en":"Please validate the figures against the source data.","zh-TW":"請將數字與源數據進行核對。"},{"en":"All results are validated against industry benchmarks.","zh-TW":"所有結果都與行業基準進行了驗證。"}]', 'phrasal verb'),
('walk through', '逐步說明；引導完成', 'to guide someone through a process step by step', '[{"en":"Let me walk you through the onboarding process.","zh-TW":"讓我逐步引導你完成入職流程。"},{"en":"She walked the client through the platform features.","zh-TW":"她逐步向客戶介紹了平台功能。"}]', 'phrasal verb'),
('yield to', '讓步；服從', 'to submit to pressure or give way to a superior force', '[{"en":"The company yielded to public pressure and revised the policy.","zh-TW":"公司在公眾壓力下讓步並修訂了政策。"},{"en":"She did not yield to the client''s unreasonable demands.","zh-TW":"她沒有屈服於客戶不合理的要求。"}]', 'phrasal verb'),
('put your best foot forward', '全力以赴；展現最佳狀態', 'to try as hard as possible to make a good impression', '[{"en":"Always put your best foot forward when meeting new clients.","zh-TW":"見新客戶時一定要全力以赴展現最佳狀態。"},{"en":"She put her best foot forward in the job interview.","zh-TW":"她在求職面試中展現了最佳狀態。"}]', 'expression'),
('put something into perspective', '以正確角度看待；客觀地評估', 'to consider something in a realistic way relative to other factors', '[{"en":"To put things into perspective our growth is still above average.","zh-TW":"以正確角度看待我們的增長仍高於平均水準。"},{"en":"She put the setback into perspective and moved forward.","zh-TW":"她客觀評估了挫折並繼續前進。"}]', 'expression'),
('raise the stakes', '提高賭注；加大風險或報酬', 'to increase the risks, importance, or rewards involved', '[{"en":"The acquisition raised the stakes for all competitors.","zh-TW":"這次收購提高了所有競爭者的賭注。"},{"en":"She raised the stakes by proposing a bolder strategy.","zh-TW":"她提出更大膽的策略提高了賭注。"}]', 'expression'),
('read the room', '察言觀色；感受現場氣氛', 'to assess the mood or expectations of others in a situation', '[{"en":"A good presenter reads the room and adjusts accordingly.","zh-TW":"優秀的演講者能察言觀色並相應調整。"},{"en":"He failed to read the room and misjudged the tone.","zh-TW":"他未能察言觀色並誤判了氣氛。"}]', 'expression'),
('rock the boat', '惹是生非；打破現狀', 'to cause trouble or upset a stable situation', '[{"en":"He was afraid to rock the boat by suggesting changes.","zh-TW":"他害怕提出改變建議而惹是生非。"},{"en":"Sometimes you need to rock the boat to drive improvement.","zh-TW":"有時你需要打破現狀來推動改進。"}]', 'expression'),
('smooth sailing', '一帆風順；順利進行', 'a situation where things proceed without difficulty', '[{"en":"After the initial phase it was smooth sailing.","zh-TW":"初期階段後一切一帆風順。"},{"en":"Getting the first client was tough but smooth sailing after that.","zh-TW":"獲得第一個客戶很艱難但之後就一帆風順了。"}]', 'expression'),
('step up to the plate', '挺身而出；承擔責任', 'to take on responsibility or rise to a challenge', '[{"en":"The team stepped up to the plate during the crisis.","zh-TW":"危機期間團隊挺身而出。"},{"en":"She stepped up to the plate when no one else would.","zh-TW":"她在沒有人願意的情況下挺身而出。"}]', 'expression'),
('swim against the tide', '逆流而上；反潮流', 'to go against the majority opinion or trend', '[{"en":"The brand swims against the tide by focusing on traditional methods.","zh-TW":"這個品牌通過專注於傳統方法逆流而上。"},{"en":"She swam against the tide and predicted the market correctly.","zh-TW":"她逆潮流而上並準確預測了市場走向。"}]', 'expression'),
('take it one step at a time', '一步一步來；循序漸進', 'to deal with things gradually and without rushing', '[{"en":"With such a complex project we should take it one step at a time.","zh-TW":"面對如此複雜的專案我們應該一步一步來。"},{"en":"Take it one step at a time and do not get overwhelmed.","zh-TW":"循序漸進不要因此感到不知所措。"}]', 'expression'),
('the writing is on the wall', '大難將至；徵兆已現', 'signs that something bad is about to happen are obvious', '[{"en":"The writing was on the wall when revenues fell three quarters in a row.","zh-TW":"連續三個季度收入下降時徵兆已現。"},{"en":"Many employees saw the writing on the wall before the layoffs.","zh-TW":"許多員工在裁員前就看到了大難將至的跡象。"}]', 'expression'),
('throw money at the problem', '砸錢解決問題；用金錢代替策略', 'to try to resolve a problem by spending money rather than fixing the cause', '[{"en":"You cannot just throw money at this problem — you need a strategy.","zh-TW":"你不能只是砸錢解決問題——你需要一個策略。"},{"en":"They threw money at the issue without diagnosing the root cause.","zh-TW":"他們未診斷根本原因就砸錢試圖解決問題。"}]', 'expression'),
('tread carefully', '謹慎行事；小心翼翼', 'to proceed with great caution', '[{"en":"Tread carefully when discussing sensitive topics with clients.","zh-TW":"與客戶討論敏感話題時要謹慎行事。"},{"en":"She tread carefully when delivering bad news.","zh-TW":"她在傳達壞消息時小心翼翼。"}]', 'expression'),
('turn a blind eye', '視而不見；裝作不知道', 'to deliberately ignore something problematic', '[{"en":"Management turned a blind eye to the compliance issues.","zh-TW":"管理層對合規問題視而不見。"},{"en":"Do not turn a blind eye to workplace misconduct.","zh-TW":"不要對職場不當行為裝作不知道。"}]', 'expression'),
('two sides of the same coin', '一體兩面；相互關聯的兩個方面', 'two things that seem different but are closely related', '[{"en":"Risk and opportunity are two sides of the same coin.","zh-TW":"風險和機會是一體兩面。"},{"en":"Customer satisfaction and profitability are two sides of the same coin.","zh-TW":"客戶滿意度和盈利能力是一體兩面。"}]', 'expression'),
('up the ante', '提高賭注；加大投入', 'to increase the stakes or demands in a situation', '[{"en":"The competitor upped the ante with aggressive pricing.","zh-TW":"競爭對手以積極的定價提高了賭注。"},{"en":"She upped the ante by proposing a 20% cost reduction.","zh-TW":"她提出20%成本降低要求加大了籌碼。"}]', 'expression'),
('fall on deaf ears', '充耳不聞；被忽視', 'to be heard but ignored or have no effect', '[{"en":"His concerns about quality fell on deaf ears.","zh-TW":"他對品質的擔憂充耳不聞。"},{"en":"The team''s suggestions fell on deaf ears.","zh-TW":"團隊的建議被忽視了。"}]', 'expression'),
('get your ducks in a row', '做好充分準備；安排妥當', 'to organize things properly before taking action', '[{"en":"Before the meeting get your ducks in a row.","zh-TW":"會議前做好充分準備。"},{"en":"We need to get our ducks in a row before the product launch.","zh-TW":"在產品發布前我們需要安排妥當。"}]', 'expression'),
('have the upper hand', '佔上風；處於優勢', 'to be in a position of advantage over others', '[{"en":"With better data we had the upper hand in the negotiation.","zh-TW":"有了更好的數據我們在談判中佔了上風。"},{"en":"Early movers have the upper hand in new markets.","zh-TW":"早期進入者在新市場中處於優勢地位。"}]', 'expression'),
('hit the spot', '正合心意；完全符合需求', 'to be exactly right or to satisfy a need perfectly', '[{"en":"That solution really hit the spot for the client.","zh-TW":"那個解決方案完全符合客戶的需求。"},{"en":"The new design hits the spot in terms of user experience.","zh-TW":"新設計在用戶體驗方面完全符合需求。"}]', 'expression'),
('lay the groundwork', '奠定基礎；打下基礎', 'to do the preparatory work for something in the future', '[{"en":"The pilot programme laid the groundwork for full rollout.","zh-TW":"試點計劃為全面推出奠定了基礎。"},{"en":"She spent months laying the groundwork for the merger.","zh-TW":"她花了幾個月為合併打下基礎。"}]', 'expression'),
('in the event that', '萬一；如果發生的話', 'if a particular situation should happen', '[{"en":"In the event that the delivery is late please inform us.","zh-TW":"萬一送貨延誤請告知我們。"},{"en":"In the event that the merger fails we have a backup plan.","zh-TW":"如果合併失敗我們有備選計劃。"}]', 'prepositional phrase'),
('pending approval', '待批准；等待批准', 'waiting for official authorization', '[{"en":"The project is on hold pending approval.","zh-TW":"專案暫停等待批准。"},{"en":"Pending approval from the board we can begin.","zh-TW":"等待董事會批准後我們即可開始。"}]', 'prepositional phrase'),
('under the auspices of', '在…的主持下；由…贊助', 'with the support or sponsorship of an organization', '[{"en":"The conference was held under the auspices of the UN.","zh-TW":"會議在聯合國的主持下舉行。"},{"en":"The project operates under the auspices of the government.","zh-TW":"該項目在政府的主持下運作。"}]', 'prepositional phrase'),
('with a grain of salt', '保留懷疑態度；半信半疑地', 'with some skepticism or caution', '[{"en":"Take the competitor''s claims with a grain of salt.","zh-TW":"對競爭對手的聲明要保留懷疑態度。"},{"en":"Initial sales projections should be taken with a grain of salt.","zh-TW":"初步銷售預測應該半信半疑。"}]', 'prepositional phrase'),
('off the top of one''s head', '不假思索地；憑印象', 'from memory without careful thought or research', '[{"en":"Off the top of my head I would estimate 50 units.","zh-TW":"憑我的印象我估計是50個單位。"},{"en":"She answered off the top of her head in the meeting.","zh-TW":"她在會議中不假思索地回答了問題。"}]', 'prepositional phrase'),
('on the premise that', '以…為前提；假設', 'based on the assumption that something is true', '[{"en":"On the premise that demand grows we are expanding.","zh-TW":"以需求增長為前提我們正在擴張。"},{"en":"We planned on the premise that budgets would not be cut.","zh-TW":"我們以預算不會被削減為前提進行規劃。"}]', 'prepositional phrase'),
('in the pipeline for', '即將推出；在籌備中', 'being prepared or planned for future release', '[{"en":"We have several updates in the pipeline for next quarter.","zh-TW":"我們有幾個更新正在籌備中將於下季度推出。"},{"en":"New features are in the pipeline for the platform.","zh-TW":"新功能正在為平台籌備中。"}]', 'prepositional phrase'),
('at the helm of', '掌舵；領導', 'in control of or leading an organization or team', '[{"en":"She has been at the helm of the company for six years.","zh-TW":"她已掌舵公司六年了。"},{"en":"With an experienced CEO at the helm the company thrived.","zh-TW":"在有經驗的執行長掌舵下公司蓬勃發展。"}]', 'prepositional phrase'),
('by mutual agreement', '經雙方同意；互相協議', 'with the consent of all involved parties', '[{"en":"The contract was terminated by mutual agreement.","zh-TW":"合同經雙方同意終止了。"},{"en":"By mutual agreement the meeting was rescheduled.","zh-TW":"經雙方同意會議重新安排了時間。"}]', 'prepositional phrase'),
('at the behest of', '在…的要求下；奉…之命', 'at the instruction or request of someone in authority', '[{"en":"At the behest of the board the audit was launched.","zh-TW":"在董事會的要求下審計啟動了。"},{"en":"At the behest of the client we revised the proposal.","zh-TW":"奉客戶之命我們修改了提案。"}]', 'prepositional phrase'),
('to the letter', '嚴格按照；一字不差地', 'following instructions or rules exactly and precisely', '[{"en":"We follow the safety protocol to the letter.","zh-TW":"我們嚴格按照安全規程執行。"},{"en":"The contract must be executed to the letter.","zh-TW":"合同必須一字不差地執行。"}]', 'prepositional phrase'),
('in pursuit of excellence', '追求卓越', 'in the effort to achieve the highest possible standards', '[{"en":"In pursuit of excellence we never stop improving.","zh-TW":"在追求卓越的過程中我們永不停止改進。"},{"en":"The team operates in pursuit of excellence in every project.","zh-TW":"團隊在每個專案中都追求卓越。"}]', 'prepositional phrase'),
('on a case-by-case basis', '逐案處理；按具體情況', 'dealing with each situation individually as it arises', '[{"en":"Exceptions will be handled on a case-by-case basis.","zh-TW":"例外情況將逐案處理。"},{"en":"Pricing is negotiated on a case-by-case basis.","zh-TW":"定價按具體情況協商。"}]', 'prepositional phrase'),
('in an advisory capacity', '以顧問身份', 'in a role providing guidance without decision-making power', '[{"en":"She joined the board in an advisory capacity.","zh-TW":"她以顧問身份加入了董事會。"},{"en":"The expert served in an advisory capacity throughout the project.","zh-TW":"專家在整個專案中以顧問身份提供服務。"}]', 'prepositional phrase'),
('in preparation for', '為…做準備；準備期間', 'in readiness or anticipation of something', '[{"en":"We held workshops in preparation for the product launch.","zh-TW":"我們舉辦了研討會為產品發布做準備。"},{"en":"In preparation for the audit all records were organized.","zh-TW":"為審計做準備所有記錄都整理好了。"}]', 'prepositional phrase'),
('on the strength of the results', '憑借結果；依據成效', 'justified or supported by the performance achieved', '[{"en":"On the strength of the results we received more funding.","zh-TW":"憑借成效我們獲得了更多資金。"},{"en":"Further contracts were awarded on the strength of the results.","zh-TW":"依據成效我們獲得了進一步的合同。"}]', 'prepositional phrase'),
('commensurate with', '與…相稱；成比例的', 'proportionate or matching in size, quality, or value', '[{"en":"Compensation is commensurate with experience and skills.","zh-TW":"薪酬與經驗和技能相稱。"},{"en":"The role offers rewards commensurate with performance.","zh-TW":"該職位提供與績效相稱的獎酬。"}]', 'prepositional phrase'),
('throughout the duration of', '在整個期間；持續整個過程', 'during the entire length of time something takes', '[{"en":"Quality must be maintained throughout the duration of the contract.","zh-TW":"在整個合同期間必須保持品質。"},{"en":"She supported the team throughout the duration of the change.","zh-TW":"她在整個變革過程中支持了團隊。"}]', 'prepositional phrase'),
('net of', '扣除…後的淨額；不含', 'after deducting or excluding something', '[{"en":"Net of taxes the profit was quite healthy.","zh-TW":"扣除稅款後利潤相當健康。"},{"en":"Please report revenue net of refunds.","zh-TW":"請報告扣除退款後的淨收入。"}]', 'prepositional phrase'),
('a tall order', '難以完成的任務；要求過高', 'a demand or requirement that is difficult to achieve', '[{"en":"Completing the project in one week is a tall order.","zh-TW":"在一週內完成這個專案是難以實現的任務。"},{"en":"Satisfying every stakeholder is always a tall order.","zh-TW":"滿足每位利益相關者總是難以實現的要求。"}]', 'business idiom');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('bang for the buck', '性價比；划算', 'value obtained relative to the money spent', '[{"en":"This software gives us great bang for the buck.","zh-TW":"這個軟體性價比非常高。"},{"en":"We want the best bang for the buck on our marketing spend.","zh-TW":"我們希望在行銷支出上獲得最高性價比。"}]', 'business idiom'),
('at the coal face', '在第一線；從事實際工作', 'doing the difficult, hands-on work directly', '[{"en":"Staff at the coal face see issues that managers miss.","zh-TW":"在第一線工作的員工看到了管理者忽略的問題。"},{"en":"Insights from those at the coal face are invaluable.","zh-TW":"來自第一線工作者的見解是無價的。"}]', 'business idiom'),
('bite off', '承擔過多；貪多嚼不爛', 'to take on more than can be handled', '[{"en":"We bit off more than we could chew with five projects at once.","zh-TW":"我們同時承擔五個專案貪多嚼不爛了。"},{"en":"Do not bite off more tasks than you can manage.","zh-TW":"不要承擔超出能力範圍的任務。"}]', 'business idiom'),
('blue chip', '績優；一流的', 'of the highest quality or most reliable type', '[{"en":"Blue chip clients bring stability to the business.","zh-TW":"績優客戶為業務帶來穩定性。"},{"en":"She only invests in blue chip companies.","zh-TW":"她只投資於一流公司。"}]', 'business idiom'),
('boots on the ground', '第一線人員；實地執行人員', 'staff actively working in the field rather than from an office', '[{"en":"We need boots on the ground in the Asian market.","zh-TW":"我們需要在亞洲市場有第一線人員。"},{"en":"Boots on the ground feedback is more reliable than surveys.","zh-TW":"第一線人員的反饋比調查更可靠。"}]', 'business idiom'),
('brain drain', '人才外流', 'the emigration or loss of educated or skilled workers', '[{"en":"Retaining talent prevents a brain drain.","zh-TW":"留住人才可以防止人才外流。"},{"en":"The company suffered a brain drain after the restructuring.","zh-TW":"重組後公司遭遇了人才外流。"}]', 'business idiom'),
('build bridges', '建立橋梁；促進溝通合作', 'to improve relationships between groups or departments', '[{"en":"The HR initiative helped build bridges between departments.","zh-TW":"人力資源計劃幫助建立了部門間的溝通橋梁。"},{"en":"She worked hard to build bridges with the new partners.","zh-TW":"她努力與新合作夥伴建立橋梁。"}]', 'business idiom'),
('burning the midnight oil', '挑燈夜戰；熬夜工作', 'working very late into the night to complete something', '[{"en":"The team was burning the midnight oil before the deadline.","zh-TW":"截止日期前團隊在挑燈夜戰。"},{"en":"She burned the midnight oil to prepare the pitch.","zh-TW":"她熬夜準備提案。"}]', 'business idiom'),
('can of worms', '棘手的問題；麻煩一堆', 'a situation that is complicated and causes many problems', '[{"en":"Changing that policy would open a can of worms.","zh-TW":"改變那項政策會引發一連串的麻煩。"},{"en":"The audit opened a can of worms.","zh-TW":"審計打開了一個棘手的局面。"}]', 'business idiom'),
('change of direction', '轉變方向；策略轉向', 'a significant shift in strategy or approach', '[{"en":"The company underwent a change of direction after the CEO changed.","zh-TW":"更換執行長後公司轉變了方向。"},{"en":"A change of direction was needed to stay competitive.","zh-TW":"為了保持競爭力需要轉變方向。"}]', 'business idiom'),
('commercial viability', '商業可行性', 'the ability of something to generate sufficient profit', '[{"en":"We evaluate the commercial viability of every new idea.","zh-TW":"我們評估每個新想法的商業可行性。"},{"en":"The project lacked commercial viability.","zh-TW":"這個專案缺乏商業可行性。"}]', 'business idiom'),
('competitive edge', '競爭優勢', 'an advantage that makes a company better than competitors', '[{"en":"Innovation gives us a competitive edge.","zh-TW":"創新給我們帶來了競爭優勢。"},{"en":"Our service quality is our competitive edge.","zh-TW":"我們的服務品質是我們的競爭優勢。"}]', 'business idiom'),
('conflict of interest', '利益衝突', 'a situation where personal interests clash with professional duties', '[{"en":"She declared a conflict of interest and recused herself.","zh-TW":"她宣布了利益衝突並迴避了投票。"},{"en":"Directors must avoid conflicts of interest.","zh-TW":"董事必須避免利益衝突。"}]', 'business idiom'),
('core competency', '核心競爭力', 'a company''s main strength or unique capability', '[{"en":"Our core competency is supply chain optimization.","zh-TW":"我們的核心競爭力是供應鏈優化。"},{"en":"Focusing on core competency drives long-term success.","zh-TW":"專注於核心競爭力推動長期成功。"}]', 'business idiom'),
('cost benefit analysis', '成本效益分析', 'a process of comparing the costs and benefits of a decision', '[{"en":"A cost benefit analysis supports our expansion decision.","zh-TW":"成本效益分析支持了我們的擴張決定。"},{"en":"Run a cost benefit analysis before investing.","zh-TW":"在投資前進行成本效益分析。"}]', 'business idiom'),
('cross the line', '越界；超出可接受範圍', 'to behave in a way that is unacceptable or unethical', '[{"en":"He crossed the line with his aggressive sales tactics.","zh-TW":"他的攻擊性銷售手法越界了。"},{"en":"The ad campaign crossed the line and was pulled.","zh-TW":"廣告活動越界後被撤回了。"}]', 'business idiom'),
('deliver on promises', '履行承諾；兌現諾言', 'to actually do what was promised or committed to', '[{"en":"We always deliver on our promises to clients.","zh-TW":"我們總是向客戶履行承諾。"},{"en":"A brand that delivers on promises builds loyalty.","zh-TW":"能履行承諾的品牌能建立忠誠度。"}]', 'business idiom'),
('zero out', '清零；歸零', 'to reduce to zero or remove completely from accounts', '[{"en":"The budget was zeroed out at year end.","zh-TW":"預算在年底被清零了。"},{"en":"She zeroed out the remaining inventory costs.","zh-TW":"她把剩餘庫存成本歸零了。"}]', 'phrasal verb'),
('draw on', '運用；借助；動用', 'to make use of a skill, resource, or experience', '[{"en":"She drew on her ten years of experience to solve the problem.","zh-TW":"她運用了十年的經驗來解決問題。"},{"en":"The company drew on its cash reserves during the downturn.","zh-TW":"經濟下滑期間公司動用了現金儲備。"}]', 'phrasal verb'),
('set out', '出發；設定；概述', 'to begin a task, or to present information in a structured way', '[{"en":"The report sets out the key findings.","zh-TW":"報告概述了關鍵發現。"},{"en":"We set out to expand our market share this year.","zh-TW":"我們今年出發去擴大市場份額。"}]', 'phrasal verb'),
('put pressure on', '向…施壓；給…壓力', 'to try to make someone do something by applying pressure', '[{"en":"Shareholders put pressure on management to improve returns.","zh-TW":"股東向管理層施壓要求提高回報。"},{"en":"Rising costs are putting pressure on profit margins.","zh-TW":"不斷上漲的成本正在給利潤率施壓。"}]', 'phrasal verb'),
('break into', '進入（新市場或行業）；闖入', 'to enter a new market or field successfully', '[{"en":"We are trying to break into the European market.","zh-TW":"我們正在嘗試進入歐洲市場。"},{"en":"Breaking into the luxury segment requires repositioning.","zh-TW":"進入高端市場需要重新定位。"}]', 'phrasal verb'),
('cash out', '套現；兌現', 'to convert an investment into cash or withdraw profits', '[{"en":"He cashed out his shares at the peak.","zh-TW":"他在股價高峰時套現了他的股份。"},{"en":"Some early investors cashed out after the IPO.","zh-TW":"部分早期投資者在IPO後套現了。"}]', 'phrasal verb'),
('walk away', '離開；放棄', 'to leave a situation or deal without reaching an agreement', '[{"en":"They walked away from the deal after negotiations broke down.","zh-TW":"談判破裂後他們放棄了這筆交易。"},{"en":"Sometimes it is better to walk away than accept bad terms.","zh-TW":"有時候放棄比接受不好的條款更明智。"}]', 'phrasal verb'),
('come up against', '遇到（困難或阻礙）', 'to encounter a problem or obstacle', '[{"en":"We came up against strong resistance from the local market.","zh-TW":"我們在本地市場遇到了強烈阻力。"},{"en":"The proposal came up against regulatory hurdles.","zh-TW":"提案遇到了監管障礙。"}]', 'phrasal verb'),
('bridge a gap', '彌合差距；縮短距離', 'to reduce the difference between two positions or groups', '[{"en":"This feature bridges a gap in user workflow.","zh-TW":"這個功能彌合了用戶工作流程中的差距。"},{"en":"Training helps bridge the gap between expectations and skills.","zh-TW":"培訓有助於彌合期望與技能之間的差距。"}]', 'phrasal verb'),
('cash in on', '藉機獲利；趁機利用', 'to take advantage of a situation for profit or benefit', '[{"en":"The company cashed in on the e-commerce boom.","zh-TW":"公司藉電商熱潮大幅獲利。"},{"en":"She cashed in on her expertise to land premium clients.","zh-TW":"她藉助自身專業知識爭取到了高端客戶。"}]', 'phrasal verb'),
('close down', '關閉；停業', 'to permanently stop operations or business', '[{"en":"The underperforming branch was closed down.","zh-TW":"表現不佳的分店被關閉了。"},{"en":"Factories closed down due to new environmental laws.","zh-TW":"由於新的環境法律工廠關閉了。"}]', 'phrasal verb'),
('cycle through', '循環；逐一處理', 'to go through a series of things in order', '[{"en":"We cycled through several vendors before deciding.","zh-TW":"我們逐一評估了幾家供應商後才做決定。"},{"en":"The system cycles through scenarios automatically.","zh-TW":"系統自動循環處理各種情況。"}]', 'phrasal verb'),
('dial back', '降低；收斂；減少', 'to reduce the level or intensity of something', '[{"en":"We need to dial back our growth expectations.","zh-TW":"我們需要降低增長預期。"},{"en":"She dialed back her tone in subsequent emails.","zh-TW":"她在後續電子郵件中降低了語氣強度。"}]', 'phrasal verb'),
('drive down', '壓低；降低', 'to reduce or lower costs, prices, or numbers', '[{"en":"Competition drives down prices over time.","zh-TW":"競爭會隨著時間推移壓低價格。"},{"en":"Automation helped drive down production costs.","zh-TW":"自動化幫助降低了生產成本。"}]', 'phrasal verb'),
('drive up', '推高；提高', 'to increase or raise costs, prices, or numbers', '[{"en":"Surging demand is driving up raw material costs.","zh-TW":"需求激增正在推高原材料成本。"},{"en":"Viral marketing drove up site traffic overnight.","zh-TW":"病毒式行銷在一夜之間推高了網站流量。"}]', 'phrasal verb'),
('firm up', '確定；使更穩固', 'to make something more definite or strengthen it', '[{"en":"Let us firm up the details before the next meeting.","zh-TW":"在下次會議前讓我們確定細節。"},{"en":"She firmed up the offer after the second interview.","zh-TW":"第二次面試後她確定了邀請。"}]', 'phrasal verb'),
('give rise to', '引起；導致；產生', 'to cause something to happen or come into existence', '[{"en":"The change in leadership gave rise to new strategies.","zh-TW":"領導層的更迭引發了新的策略。"},{"en":"Miscommunication can give rise to serious problems.","zh-TW":"溝通不良可能引發嚴重問題。"}]', 'phrasal verb'),
('hand back', '歸還；退還', 'to return something to its original owner or holder', '[{"en":"After the audit the documents were handed back.","zh-TW":"審計結束後文件被歸還了。"},{"en":"He handed back control of the project to the original team.","zh-TW":"他將專案控制權歸還給了原來的團隊。"}]', 'phrasal verb'),
('burn the candle at both ends', '日夜操勞；精力過度消耗', 'to work excessively hard, sleeping and resting very little', '[{"en":"He was burning the candle at both ends during the product launch.","zh-TW":"他在產品發布期間日夜操勞。"},{"en":"Burning the candle at both ends leads to burnout.","zh-TW":"日夜操勞最終會導致過勞。"}]', 'expression'),
('carry the day', '大獲全勝；贏得勝利', 'to win or succeed decisively in an argument or competition', '[{"en":"Her strong data carried the day in the board presentation.","zh-TW":"她強有力的數據在董事會簡報中大獲全勝。"},{"en":"Good preparation carried the day in the negotiation.","zh-TW":"充分準備贏得了談判的勝利。"}]', 'expression'),
('catch someone off guard', '出其不意；令人措手不及', 'to surprise someone who is unprepared', '[{"en":"The competitor''s announcement caught us off guard.","zh-TW":"競爭對手的公告讓我們措手不及。"},{"en":"Be prepared so clients cannot catch you off guard.","zh-TW":"要做好準備以免客戶讓你措手不及。"}]', 'expression'),
('change of heart', '改變主意；心意改變', 'a change in attitude or decision', '[{"en":"He had a change of heart and withdrew the proposal.","zh-TW":"他改變了主意並撤回了提案。"},{"en":"A change of heart led her to accept the offer.","zh-TW":"改變主意讓她接受了邀請。"}]', 'expression'),
('come clean', '坦白交代；承認錯誤', 'to tell the truth after concealing it', '[{"en":"He came clean about the financial irregularities.","zh-TW":"他坦白交代了財務不規則事項。"},{"en":"It is better to come clean early than hide mistakes.","zh-TW":"早坦白比隱瞞錯誤更好。"}]', 'expression'),
('count one''s chickens', '過早樂觀；未成功就先慶祝', 'to assume success before it is certain', '[{"en":"Do not count your chickens before the deal is signed.","zh-TW":"合同簽署前不要過早樂觀。"},{"en":"She counted her chickens and was disappointed when the deal fell through.","zh-TW":"她過早慶祝結果交易失敗令她失望。"}]', 'expression'),
('cut both ways', '雙面刃；利弊兼具', 'to have both positive and negative effects', '[{"en":"That policy cuts both ways — it helps and hurts different teams.","zh-TW":"那項政策是雙面刃——對不同團隊有利有弊。"},{"en":"Price cuts cut both ways in a competitive market.","zh-TW":"在競爭市場中降價是雙面刃。"}]', 'expression'),
('do a U-turn', '來個大轉彎；完全改變立場', 'to completely reverse a position or decision', '[{"en":"The company did a U-turn on its pricing strategy.","zh-TW":"公司在定價策略上來了個大轉彎。"},{"en":"Management did a U-turn after the staff backlash.","zh-TW":"員工強烈反對後管理層完全改變了立場。"}]', 'expression'),
('drop the ball', '搞砸；失誤；掉球', 'to fail to handle a responsibility properly', '[{"en":"We dropped the ball on the client''s request.","zh-TW":"我們在客戶請求方面搞砸了。"},{"en":"The project failed because someone dropped the ball.","zh-TW":"有人失誤導致專案失敗。"}]', 'expression'),
('earn one''s stripes', '在實踐中證明自己；靠努力贏得地位', 'to prove oneself through hard work and experience', '[{"en":"She earned her stripes managing difficult clients.","zh-TW":"她透過管理難相處的客戶證明了自己。"},{"en":"You need to earn your stripes before leading a team.","zh-TW":"領導團隊前你需要靠努力證明自己的價值。"}]', 'expression'),
('every cloud has a silver lining', '否極泰來；每件壞事都有其好的一面', 'every difficult situation contains a positive aspect', '[{"en":"The lost contract forced us to improve — every cloud has a silver lining.","zh-TW":"失去合同迫使我們改進——否極泰來。"},{"en":"Even this setback has a silver lining if we look.","zh-TW":"即使是這次挫折也有其好的一面。"}]', 'expression'),
('face the facts', '面對現實；承認事實', 'to accept the truth of a situation even if unpleasant', '[{"en":"We need to face the facts — our market share is declining.","zh-TW":"我們需要面對現實——我們的市場份額正在下降。"},{"en":"She faced the facts and restructured the team.","zh-TW":"她面對現實並重組了團隊。"}]', 'expression'),
('gain traction', '取得進展；越來越受到重視', 'to start to become successful or accepted', '[{"en":"The new product is gaining traction in the market.","zh-TW":"新產品正在市場上越來越受到重視。"},{"en":"Our social media campaign is finally gaining traction.","zh-TW":"我們的社交媒體活動終於取得了進展。"}]', 'expression'),
('get ahead of oneself', '操之過急；走在自己的能力之前', 'to be too hasty or ambitious before being ready', '[{"en":"Do not get ahead of yourself — confirm the facts first.","zh-TW":"不要操之過急——先確認事實。"},{"en":"She got ahead of herself and overpromised.","zh-TW":"她操之過急做出了過度承諾。"}]', 'expression'),
('get wind of', '得知；聞到風聲', 'to find out about something that was meant to be secret', '[{"en":"Competitors got wind of our product launch plans.","zh-TW":"競爭對手得知了我們的產品發布計劃。"},{"en":"She got wind of the restructuring before it was announced.","zh-TW":"她在宣布重組前就聞到了風聲。"}]', 'expression');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('go belly up', '倒閉；失敗', 'to fail or go bankrupt', '[{"en":"Three competitors went belly up during the recession.","zh-TW":"三家競爭對手在經濟衰退期間倒閉了。"},{"en":"The startup went belly up after the funding dried up.","zh-TW":"資金枯竭後這家新創公司倒閉了。"}]', 'expression'),
('grease the wheels', '疏通關係；使運作更順暢', 'to do things that make a process work more smoothly', '[{"en":"A small concession helped grease the wheels of negotiation.","zh-TW":"一個小小的讓步幫助疏通了談判的進展。"},{"en":"She used her network to grease the wheels of the project.","zh-TW":"她利用人脈使專案運作更順暢。"}]', 'expression'),
('from the outset', '從一開始；自始', 'from the very beginning', '[{"en":"Clear expectations should be set from the outset.","zh-TW":"從一開始就應該設定清晰的期望。"},{"en":"From the outset the team knew the project was ambitious.","zh-TW":"從一開始團隊就知道這個專案很有野心。"}]', 'prepositional phrase'),
('in tandem with', '與…同步；配合', 'at the same time as or in coordination with', '[{"en":"Growth targets were set in tandem with hiring plans.","zh-TW":"增長目標與招聘計劃同步設定。"},{"en":"Marketing works in tandem with sales at this company.","zh-TW":"在這家公司行銷與銷售協同工作。"}]', 'prepositional phrase'),
('courtesy of', '承蒙…提供；因…而實現', 'provided by or thanks to someone or something', '[{"en":"The training was offered courtesy of our sponsor.","zh-TW":"培訓承蒙我們的贊助商提供。"},{"en":"Courtesy of the new system we processed twice the orders.","zh-TW":"因為新系統我們處理了兩倍的訂單。"}]', 'prepositional phrase'),
('on a tight deadline', '在緊迫的截止日期下', 'working with very little time remaining', '[{"en":"The team is on a tight deadline and needs extra support.","zh-TW":"團隊在緊迫的截止日期下需要額外支援。"},{"en":"On a tight deadline she still delivered excellent work.","zh-TW":"在緊迫的截止日期下她仍然交出了優秀的工作。"}]', 'prepositional phrase'),
('at a standstill', '停滯不前；陷入僵局', 'completely stopped or not progressing', '[{"en":"Production was at a standstill after the power cut.","zh-TW":"停電後生產陷入停滯。"},{"en":"Negotiations are at a standstill due to budget issues.","zh-TW":"由於預算問題談判陷入僵局。"}]', 'prepositional phrase'),
('at someone''s disposal', '可供某人使用；任某人支配', 'available for a particular person to use freely', '[{"en":"All resources are at your disposal for this project.","zh-TW":"所有資源都可供你在這個專案中使用。"},{"en":"She put her expertise at the team''s disposal.","zh-TW":"她將自己的專業知識供團隊任意使用。"}]', 'prepositional phrase'),
('in collaboration with', '與…合作；共同', 'working jointly with others', '[{"en":"The report was written in collaboration with three universities.","zh-TW":"報告是與三所大學合作撰寫的。"},{"en":"In collaboration with local agencies we launched the project.","zh-TW":"我們與當地機構合作啟動了專案。"}]', 'prepositional phrase'),
('in deference to', '出於對…的尊重；考量到', 'out of respect or in consideration of someone''s wishes', '[{"en":"In deference to the client''s wishes the deadline was extended.","zh-TW":"出於對客戶意願的尊重截止日期被延長了。"},{"en":"In deference to the board we revised the proposal.","zh-TW":"考量到董事會的意見我們修改了提案。"}]', 'prepositional phrase'),
('on target', '按計劃進行；達標', 'progressing as planned; achieving goals as expected', '[{"en":"The project is on target for completion by Q4.","zh-TW":"專案按計劃預計在第四季完成。"},{"en":"We are on target to exceed annual sales goals.","zh-TW":"我們有望超額完成年度銷售目標。"}]', 'prepositional phrase'),
('in partnership', '以合夥方式；共同合作', 'working together as partners', '[{"en":"We launched the campaign in partnership with a media agency.","zh-TW":"我們與一家媒體公司合作推出了這次活動。"},{"en":"Working in partnership amplifies our reach.","zh-TW":"合作擴大了我們的影響範圍。"}]', 'prepositional phrase'),
('on an ongoing basis', '持續地；長期地', 'happening continuously or regularly over time', '[{"en":"Performance is reviewed on an ongoing basis.","zh-TW":"績效會持續進行評估。"},{"en":"We communicate with clients on an ongoing basis.","zh-TW":"我們持續與客戶保持溝通。"}]', 'prepositional phrase'),
('within reach', '在可企及的範圍內；觸手可及', 'close enough to be achieved or obtained', '[{"en":"Profitability is now within reach.","zh-TW":"盈利能力現在觸手可及。"},{"en":"The funding goal is within reach after the last round.","zh-TW":"上一輪融資後資金目標近在咫尺。"}]', 'prepositional phrase'),
('in recognition of', '為了表彰；以表示肯定', 'to show appreciation or acknowledgment of something', '[{"en":"She received a bonus in recognition of her leadership.","zh-TW":"她因領導力而獲得了獎金表彰。"},{"en":"In recognition of his service the team gave him an award.","zh-TW":"為了表彰他的貢獻團隊頒給了他一個獎項。"}]', 'prepositional phrase'),
('by all accounts', '據大家說；就各方看法而言', 'according to most people or all available evidence', '[{"en":"By all accounts the launch was a great success.","zh-TW":"據大家說這次發布會非常成功。"},{"en":"By all accounts she is an exceptional negotiator.","zh-TW":"就各方看法而言她是一位出色的談判者。"}]', 'prepositional phrase'),
('short of', '不足；差一點；除了', 'lacking a required amount, or except for something', '[{"en":"We fell short of the quarterly target by 5%.","zh-TW":"我們的季度目標差了5%。"},{"en":"Short of a last-minute deal the merger is off.","zh-TW":"除非最後一刻達成協議否則合並告吹。"}]', 'prepositional phrase'),
('to the tune of', '高達；以…的金額', 'to the amount of (usually a large sum)', '[{"en":"The renovation cost to the tune of 5 million dollars.","zh-TW":"翻新費用高達500萬美元。"},{"en":"They invested to the tune of 20 million in the startup.","zh-TW":"他們向這家新創公司投資了高達2000萬。"}]', 'prepositional phrase'),
('in the absence', '在缺乏…的情況下', 'when something important is not present or available', '[{"en":"In the absence of clear data we will estimate.","zh-TW":"在缺乏明確數據的情況下我們將進行估算。"},{"en":"In the absence of the director the deputy took charge.","zh-TW":"在總監缺席的情況下副手接管了。"}]', 'prepositional phrase'),
('drop in the bucket', '九牛一毛；微不足道的數量', 'a very small amount compared to what is needed', '[{"en":"The savings are a drop in the bucket compared to total costs.","zh-TW":"這些節省與總成本相比是九牛一毛。"},{"en":"Our marketing budget is a drop in the bucket against global players.","zh-TW":"我們的行銷預算與全球參與者相比微不足道。"}]', 'business idiom'),
('early adopter', '早期採用者；先行使用者', 'someone who starts using a new product or technology early', '[{"en":"Early adopters provide valuable feedback on new features.","zh-TW":"早期採用者對新功能提供了寶貴的反饋。"},{"en":"We offered early adopters a discounted subscription.","zh-TW":"我們為早期採用者提供了折扣訂閱。"}]', 'business idiom'),
('expand the market', '開拓市場；擴大市場', 'to grow the number of customers or geographic reach', '[{"en":"Our goal is to expand the market for renewable energy.","zh-TW":"我們的目標是開拓可再生能源市場。"},{"en":"Localized content helped expand the market in Asia.","zh-TW":"在地化內容幫助在亞洲拓展了市場。"}]', 'business idiom'),
('eye-opener', '令人大開眼界的事；大開眼界', 'something that is surprising and reveals new information', '[{"en":"The audit was an eye-opener for senior management.","zh-TW":"審計對高層管理者來說是大開眼界的事。"},{"en":"Visiting the factory was a real eye-opener.","zh-TW":"參觀工廠真的讓人大開眼界。"}]', 'business idiom'),
('fall short', '達不到；不足', 'to not meet the required standard or amount', '[{"en":"Sales fell short of the Q3 target by 10%.","zh-TW":"銷售額比第三季度目標低了10%。"},{"en":"The proposal fell short of what the client expected.","zh-TW":"提案未能達到客戶的期望。"}]', 'business idiom'),
('fast follower', '快速跟進者；敏捷跟跑策略', 'a company that lets others innovate then quickly adapts the winning approach', '[{"en":"Being a fast follower reduces the risk of being first.","zh-TW":"作為快速跟進者降低了率先行動的風險。"},{"en":"Their fast follower strategy paid off in the mobile market.","zh-TW":"他們的快速跟進策略在移動市場上獲得了回報。"}]', 'business idiom'),
('financial year end', '財政年度結束；年末', 'the conclusion of the twelve-month accounting period', '[{"en":"All budgets must be reconciled at financial year end.","zh-TW":"所有預算必須在財政年度結束時核對。"},{"en":"She prepared the annual report for financial year end.","zh-TW":"她為財政年度結束準備了年度報告。"}]', 'business idiom'),
('fly high', '飛黃騰達；業績卓越', 'to be very successful or profitable', '[{"en":"The company is flying high after the successful IPO.","zh-TW":"成功上市後公司飛黃騰達。"},{"en":"Their new product line is flying high in consumer reviews.","zh-TW":"他們的新產品線在消費者評論中業績卓越。"}]', 'business idiom'),
('foothold', '立足點；初步進入', 'an initial and secure position in a competitive market', '[{"en":"We established a foothold in Southeast Asia this year.","zh-TW":"今年我們在東南亞建立了立足點。"},{"en":"Gaining a foothold in the enterprise market was difficult.","zh-TW":"在企業市場取得立足點很困難。"}]', 'business idiom'),
('free ride', '搭便車；不勞而獲', 'to benefit from others'' work without contributing', '[{"en":"You cannot get a free ride in a results-driven culture.","zh-TW":"在注重結果的文化中你不能搭便車。"},{"en":"He was seen as taking a free ride on the team''s success.","zh-TW":"他被認為在搭團隊成功的便車。"}]', 'business idiom'),
('full steam ahead', '全力前進；全速推進', 'moving forward with maximum effort and speed', '[{"en":"With budget approved it was full steam ahead.","zh-TW":"預算獲批後我們全力前進。"},{"en":"The team went full steam ahead on the product launch.","zh-TW":"團隊全速推進產品發布。"}]', 'business idiom'),
('get a foot in the door', '取得初步機會；邁出第一步', 'to gain an initial opportunity in a competitive field', '[{"en":"A small pilot project helped us get a foot in the door.","zh-TW":"一個小型試點項目幫助我們邁出了第一步。"},{"en":"She got a foot in the door through an internship.","zh-TW":"她通過實習獲得了初步機會。"}]', 'business idiom'),
('get on board', '加入；同意；支持', 'to join a plan, team, or cause enthusiastically', '[{"en":"We need to get the sales team on board with the new process.","zh-TW":"我們需要讓銷售團隊支持新流程。"},{"en":"Once the CEO got on board the project accelerated.","zh-TW":"一旦執行長加入專案就加速了。"}]', 'business idiom'),
('get the upper hand', '佔上風；取得優勢', 'to gain an advantage over others in a contest', '[{"en":"They got the upper hand by reducing prices first.","zh-TW":"他們率先降價而佔了上風。"},{"en":"Better data gives us the upper hand in negotiations.","zh-TW":"更好的數據讓我們在談判中佔有優勢。"}]', 'business idiom'),
('golden opportunity', '千載難逢的機會', 'an exceptionally good chance to achieve something', '[{"en":"This market gap is a golden opportunity for us.","zh-TW":"這個市場缺口對我們來說是千載難逢的機會。"},{"en":"Do not let this golden opportunity pass.","zh-TW":"不要讓這個千載難逢的機會溜走。"}]', 'business idiom'),
('grab the bull by the horns', '勇於面對難題；迎難而上', 'to tackle a difficult problem directly and decisively', '[{"en":"It is time to grab the bull by the horns and restructure.","zh-TW":"是時候勇於面對難題進行重組了。"},{"en":"She grabbed the bull by the horns and resolved the crisis.","zh-TW":"她迎難而上解決了危機。"}]', 'business idiom'),
('grow organically', '有機增長；自然增長', 'to grow through internal development rather than acquisitions', '[{"en":"We grew organically rather than through acquisitions.","zh-TW":"我們通過有機增長而非收購來發展。"},{"en":"Growing organically builds a more sustainable business.","zh-TW":"有機增長建立了更可持續的業務。"}]', 'business idiom'),
('gut feeling', '直覺；第六感', 'a strong intuition about something without clear evidence', '[{"en":"His gut feeling told him the deal was risky.","zh-TW":"他的直覺告訴他這筆交易有風險。"},{"en":"Sometimes gut feeling is as important as data in decisions.","zh-TW":"有時直覺在決策中與數據同樣重要。"}]', 'business idiom'),
('hands-on approach', '親力親為；實踐型方式', 'getting directly involved in work rather than just supervising', '[{"en":"The CEO takes a hands-on approach to product development.","zh-TW":"執行長對產品開發採取親力親為的方式。"},{"en":"A hands-on approach helps managers understand daily challenges.","zh-TW":"親力親為的方式幫助管理者了解日常挑戰。"}]', 'business idiom'),
('hard sell', '強力推銷；強硬銷售', 'an aggressive attempt to persuade someone to buy or agree', '[{"en":"A hard sell approach often alienates potential clients.","zh-TW":"強力推銷往往會疏遠潛在客戶。"},{"en":"She avoided the hard sell and focused on building trust.","zh-TW":"她避免了強硬推銷而是專注於建立信任。"}]', 'business idiom'),
('liaise with', '聯絡；協調', 'to communicate and cooperate with another person or organization', '[{"en":"She liaises with the finance team on budget matters.","zh-TW":"她與財務團隊就預算事宜保持聯絡。"},{"en":"We liaise closely with clients to understand their needs.","zh-TW":"我們與客戶密切協調以了解他們的需求。"}]', 'phrasal verb'),
('nail down', '確定；明確固定', 'to specify exactly or finalize clearly', '[{"en":"Let us nail down the exact scope of work.","zh-TW":"讓我們明確固定工作範圍。"},{"en":"She nailed down the project timeline in the first meeting.","zh-TW":"她在第一次會議中確定了專案時間表。"}]', 'phrasal verb'),
('phase out of', '逐步淘汰；逐漸停止使用', 'to eliminate something gradually over time', '[{"en":"Fossil fuels are being phased out of the energy mix.","zh-TW":"化石燃料正被逐步淘汰出能源組合。"},{"en":"We are phasing this legacy product out of the lineup.","zh-TW":"我們正在將這款舊產品從產品線中逐步淘汰。"}]', 'phrasal verb'),
('plug into', '融入；接入；利用', 'to connect or integrate with a larger system or community', '[{"en":"Our API plugs into most existing CRM systems.","zh-TW":"我們的API可以接入大多數現有CRM系統。"},{"en":"She plugged into the startup ecosystem immediately.","zh-TW":"她立即融入了新創生態系統。"}]', 'phrasal verb'),
('prime for', '為…做好準備；使準備就緒', 'to prepare something for a particular purpose', '[{"en":"We need to prime the market before the launch.","zh-TW":"我們需要在發布前為市場做好準備。"},{"en":"Months of training primed the team for the expansion.","zh-TW":"幾個月的培訓使團隊為擴張做好了準備。"}]', 'phrasal verb'),
('put a stop to', '終止；阻止', 'to cause something harmful to end', '[{"en":"Management put a stop to the unauthorized spending.","zh-TW":"管理層終止了未經授權的支出。"},{"en":"She put a stop to the meeting when it became unproductive.","zh-TW":"當會議變得低效時她終止了會議。"}]', 'phrasal verb'),
('qualify for', '符合資格；具備條件', 'to meet the requirements for something', '[{"en":"Small businesses may qualify for the government grant.","zh-TW":"小企業可能符合政府補助的資格。"},{"en":"She qualifies for the leadership development programme.","zh-TW":"她具備參加領導力發展計劃的資格。"}]', 'phrasal verb'),
('read through', '通讀；仔細閱讀', 'to read something carefully from beginning to end', '[{"en":"Please read through the agreement before signing.","zh-TW":"簽署前請仔細通讀協議。"},{"en":"She read through the report and flagged three issues.","zh-TW":"她通讀了報告並標記了三個問題。"}]', 'phrasal verb'),
('recover from', '從…中恢復；恢復元氣', 'to return to a normal state after a setback', '[{"en":"The company is slowly recovering from the market downturn.","zh-TW":"公司正在緩慢地從市場下滑中恢復。"},{"en":"She recovered from the failed campaign with a fresh strategy.","zh-TW":"她以新策略從失敗的活動中恢復。"}]', 'phrasal verb'),
('review against', '與…對照審查；對比評審', 'to evaluate by comparing against a standard or baseline', '[{"en":"We review results against last year''s benchmarks.","zh-TW":"我們將結果與去年的基準進行對照審查。"},{"en":"She reviewed the proposal against the client requirements.","zh-TW":"她將提案與客戶要求進行了對比評審。"}]', 'phrasal verb'),
('reward with', '以…獎勵；給予獎勵', 'to give something positive in return for good performance', '[{"en":"High performers are rewarded with performance bonuses.","zh-TW":"績效優秀者以績效獎金獎勵。"},{"en":"She was rewarded with a promotion for her hard work.","zh-TW":"她因努力工作而以晉升為獎勵。"}]', 'phrasal verb');
INSERT INTO phrases (phrase, meaning_zh, meaning_en, examples_json, category) VALUES
('scale across', '跨範圍擴展；橫向擴展', 'to expand or apply a model across multiple areas', '[{"en":"We plan to scale the solution across all regions.","zh-TW":"我們計劃在所有地區擴展這個解決方案。"},{"en":"The approach scaled across three product lines successfully.","zh-TW":"這個方法成功地在三條產品線上橫向擴展了。"}]', 'phrasal verb'),
('shut out', '排除；拒之門外', 'to exclude or prevent from accessing or participating', '[{"en":"Strict regulations shut out new competitors.","zh-TW":"嚴格的法規將新競爭者拒之門外。"},{"en":"She felt shut out of the decision-making process.","zh-TW":"她感到被排除在決策過程之外。"}]', 'phrasal verb'),
('sign off', '批准；結束；簽字確認', 'to give final approval or sign to confirm completion', '[{"en":"The director needs to sign off on all purchases over 5000.","zh-TW":"所有超過5000的採購都需要總監簽字確認。"},{"en":"She signed off on the project before handing it over.","zh-TW":"她在移交前批准了該專案。"}]', 'phrasal verb'),
('sleep on it', '等明天再決定；先想一想', 'to take more time before making a decision', '[{"en":"It is a big decision — sleep on it before responding.","zh-TW":"這是個重大決定——先想一想再回覆。"},{"en":"She slept on it and came back with a better answer.","zh-TW":"她想了想後給出了更好的答案。"}]', 'phrasal verb'),
('slow roll', '緩慢推進；刻意拖延', 'to do something slowly and deliberately, often to delay', '[{"en":"They slow rolled the integration to manage disruption.","zh-TW":"他們緩慢推進整合以管理干擾。"},{"en":"Do not slow roll the update — clients are waiting.","zh-TW":"不要刻意拖延更新——客戶在等待。"}]', 'phrasal verb'),
('speak up for', '為…發聲；支持', 'to defend or advocate on behalf of someone or something', '[{"en":"She spoke up for her team when management criticized them.","zh-TW":"管理層批評她的團隊時她為他們發聲。"},{"en":"Be willing to speak up for what you believe in.","zh-TW":"要願意為你所相信的事情發聲。"}]', 'phrasal verb'),
('stake out', '確立立場；劃定範圍', 'to establish a clear position or claim something firmly', '[{"en":"She staked out a clear position in the debate.","zh-TW":"她在辯論中確立了清晰的立場。"},{"en":"The company staked out its territory in the premium segment.","zh-TW":"公司在高端市場劃定了自己的領域。"}]', 'phrasal verb'),
('stand down', '撤退；停止；辭職', 'to withdraw from a position or cease an action', '[{"en":"The executive stood down under board pressure.","zh-TW":"在董事會壓力下高管辭職了。"},{"en":"Both parties agreed to stand down from their positions.","zh-TW":"雙方同意撤退各自的立場。"}]', 'phrasal verb'),
('steer clear of', '避開；遠離', 'to avoid something or someone deliberately', '[{"en":"Steer clear of political topics in business meetings.","zh-TW":"在商務會議中遠離政治話題。"},{"en":"She steered clear of the volatile market segments.","zh-TW":"她避開了波動劇烈的市場細分領域。"}]', 'phrasal verb'),
('have one''s work cut out', '面臨艱鉅任務；任務繁重', 'to have a very difficult task ahead', '[{"en":"With three deadlines this week she has her work cut out.","zh-TW":"這週有三個截止日期她面臨艱鉅任務。"},{"en":"The new director has his work cut out turning around the division.","zh-TW":"新主管面臨扭轉部門局面的艱鉅任務。"}]', 'expression'),
('hedge one''s bets', '雙邊下注；降低風險', 'to reduce risk by supporting more than one option', '[{"en":"By investing in multiple markets we hedge our bets.","zh-TW":"通過投資多個市場我們降低了風險。"},{"en":"He hedged his bets by keeping two options open.","zh-TW":"他通過保留兩個選項來雙邊下注。"}]', 'expression'),
('hold the fort', '守住陣地；維持秩序', 'to manage a situation while others are away', '[{"en":"Can you hold the fort while I am at the conference?","zh-TW":"我去參加會議時你能維持秩序嗎？"},{"en":"She held the fort for a month during the director''s leave.","zh-TW":"總監請假期間她守住了陣地一個月。"}]', 'expression'),
('in hot water', '陷入麻煩；有大麻煩', 'in a difficult or troubled situation', '[{"en":"The company is in hot water over data privacy issues.","zh-TW":"公司因數據隱私問題陷入了麻煩。"},{"en":"He found himself in hot water after the announcement.","zh-TW":"公告後他發現自己惹上了大麻煩。"}]', 'expression'),
('jump the gun', '操之過急；倉促行動', 'to act before the appropriate time', '[{"en":"Do not jump the gun and announce before approval.","zh-TW":"在獲得批准前不要操之過急地發布公告。"},{"en":"He jumped the gun and sent the email before the deal closed.","zh-TW":"他在交易完成前倉促地發送了電子郵件。"}]', 'expression'),
('keep a low profile', '保持低調；不引人注目', 'to avoid attracting attention or publicity', '[{"en":"During the investigation the company kept a low profile.","zh-TW":"調查期間公司保持了低調。"},{"en":"She kept a low profile after the failed product launch.","zh-TW":"產品發布失敗後她保持了低調。"}]', 'expression'),
('kick the can down the road', '拖延問題；把問題留給以後', 'to postpone dealing with a problem to a future time', '[{"en":"We cannot keep kicking this issue down the road.","zh-TW":"我們不能一直拖延這個問題。"},{"en":"Kicking the can down the road only makes things worse.","zh-TW":"把問題留給以後只會讓事情更糟。"}]', 'expression'),
('lead by example', '以身作則', 'to demonstrate through one''s own behavior the standards expected of others', '[{"en":"Effective managers lead by example.","zh-TW":"有效的管理者以身作則。"},{"en":"She leads by example by always being on time.","zh-TW":"她通過總是準時到達來以身作則。"}]', 'expression'),
('look at the big picture', '著眼大局；從整體角度考慮', 'to consider the overall situation rather than details', '[{"en":"When stressed look at the big picture and priorities.","zh-TW":"壓力大時要著眼大局和優先事項。"},{"en":"She always looks at the big picture before deciding.","zh-TW":"她在決定前總是從整體角度考慮。"}]', 'expression'),
('lose the plot', '失控；亂了陣腳；失去重點', 'to lose focus or control of a situation', '[{"en":"The team lost the plot when three managers left at once.","zh-TW":"三位管理者同時離開後團隊亂了陣腳。"},{"en":"Do not lose the plot when clients push for changes.","zh-TW":"當客戶推動變更時不要失去重點。"}]', 'expression'),
('make a mark', '留下印記；創造顯著影響', 'to have a lasting, positive impact on something', '[{"en":"She made a mark in the tech industry with her innovation.","zh-TW":"她以創新在科技業留下了印記。"},{"en":"This product made a real mark on the market.","zh-TW":"這款產品對市場產生了真正的顯著影響。"}]', 'expression'),
('make or break', '成敗關鍵；決定成敗', 'determining whether something succeeds or fails', '[{"en":"This quarter is make or break for the startup.","zh-TW":"這個季度是新創公司成敗的關鍵。"},{"en":"The negotiation is make or break for the partnership.","zh-TW":"這次談判是合作關係成敗的決定性因素。"}]', 'expression'),
('make the cut', '入選；符合標準', 'to meet the standard required to be chosen or included', '[{"en":"Only three candidates made the cut.","zh-TW":"只有三位候選人入選。"},{"en":"Her presentation made the cut for the final pitch.","zh-TW":"她的簡報入選了最終提案。"}]', 'expression'),
('mind the gap', '注意差距；填補缺口', 'to be aware of and address gaps or weaknesses', '[{"en":"Mind the gap between promised and delivered service.","zh-TW":"注意承諾服務與實際交付之間的差距。"},{"en":"Regularly mind the gap in skills within your team.","zh-TW":"定期注意並填補團隊內的技能差距。"}]', 'expression'),
('move mountains', '排除萬難；取得非凡成就', 'to accomplish something very difficult', '[{"en":"She moved mountains to get the project approved.","zh-TW":"她排除萬難讓專案獲得了批准。"},{"en":"The team moved mountains to deliver on time.","zh-TW":"團隊排除萬難準時交付。"}]', 'expression'),
('nail the landing', '完美收尾；漂亮地完成', 'to execute a conclusion or final stage perfectly', '[{"en":"She nailed the landing with a compelling call to action.","zh-TW":"她以有力的行動呼籲完美收尾了簡報。"},{"en":"After months of preparation they nailed the landing.","zh-TW":"經過幾個月的準備他們漂亮地完成了任務。"}]', 'expression'),
('name of the game', '關鍵所在；核心要素', 'the most important quality or skill needed for success', '[{"en":"In e-commerce speed is the name of the game.","zh-TW":"在電商中速度是關鍵所在。"},{"en":"Client retention is the name of the game in our industry.","zh-TW":"在我們的行業中客戶留存是核心要素。"}]', 'expression'),
('on borrowed time', '時日無多；快到盡頭', 'continuing in a situation that is likely to end soon', '[{"en":"That business model is on borrowed time.","zh-TW":"那個商業模式時日無多了。"},{"en":"Without innovation the product line is on borrowed time.","zh-TW":"沒有創新這條產品線快到盡頭了。"}]', 'expression'),
('own the outcome', '承擔結果責任；掌控成果', 'to take full responsibility for the result of one''s actions', '[{"en":"Leaders must own the outcome whether positive or negative.","zh-TW":"領導者必須對成果承擔責任無論是正面還是負面。"},{"en":"She owned the outcome and presented it transparently.","zh-TW":"她承擔了成果責任並透明地呈報了結果。"}]', 'expression'),
('play to one''s strengths', '發揮優勢；利用強項', 'to use one''s best qualities or abilities to gain advantage', '[{"en":"Play to your strengths and let others handle the rest.","zh-TW":"發揮你的優勢讓其他人處理其餘事宜。"},{"en":"The team played to its strengths in the final pitch.","zh-TW":"團隊在最後提案中發揮了自己的優勢。"}]', 'expression'),
('in hindsight', '事後看來；回頭來看', 'looking back at the past with new understanding', '[{"en":"In hindsight we should have launched earlier.","zh-TW":"事後看來我們應該更早推出的。"},{"en":"In hindsight the acquisition was a mistake.","zh-TW":"回頭來看這次收購是個錯誤。"}]', 'prepositional phrase'),
('going forward', '今後；從現在起', 'from now on; in the future', '[{"en":"Going forward all approvals must be documented.","zh-TW":"從現在起所有批准都必須記錄在案。"},{"en":"Going forward we will focus on quality over speed.","zh-TW":"今後我們將注重品質而非速度。"}]', 'prepositional phrase'),
('on the agenda', '在議程上；待討論的', 'listed as a topic to be discussed at a meeting', '[{"en":"Budget allocation is on the agenda for today.","zh-TW":"預算分配在今天的議程上。"},{"en":"She made sure sustainability was on the agenda.","zh-TW":"她確保永續發展被列入了議程。"}]', 'prepositional phrase'),
('on the horizon', '即將來臨；在不遠的將來', 'expected to happen in the near future', '[{"en":"A major product update is on the horizon.","zh-TW":"一個重大產品更新即將來臨。"},{"en":"With new regulations on the horizon we must prepare.","zh-TW":"隨著新法規即將來臨我們必須做好準備。"}]', 'prepositional phrase'),
('in step with', '與…步調一致；緊跟', 'in agreement or keeping pace with something', '[{"en":"Our pricing is in step with market expectations.","zh-TW":"我們的定價與市場期望一致。"},{"en":"The strategy is in step with the latest consumer trends.","zh-TW":"該策略緊跟最新的消費者趨勢。"}]', 'prepositional phrase'),
('in line for', '有望晉升為；即將獲得', 'positioned to receive or be appointed to something', '[{"en":"She is in line for the regional director position.","zh-TW":"她有望晉升為區域總監。"},{"en":"He is in line for a significant pay rise.","zh-TW":"他即將獲得大幅加薪。"}]', 'prepositional phrase'),
('in transition', '處於過渡期；轉型中', 'in the process of changing from one state to another', '[{"en":"The company is in transition to a new operating model.","zh-TW":"公司正處於轉型到新運作模式的過渡期。"},{"en":"She is in transition between her old and new roles.","zh-TW":"她正處於新舊職位之間的過渡期。"}]', 'prepositional phrase'),
('up to standard', '達到標準；符合要求', 'meeting the required level of quality or performance', '[{"en":"The product was not up to standard and was recalled.","zh-TW":"產品未達到標準並被召回了。"},{"en":"All deliverables must be up to standard before release.","zh-TW":"所有交付物在發布前必須達到標準。"}]', 'prepositional phrase'),
('in default', '違約；拖欠', 'having failed to meet a financial or legal obligation', '[{"en":"The company is in default on its loan repayments.","zh-TW":"公司在貸款還款上違約了。"},{"en":"Failure to deliver constitutes being in default.","zh-TW":"未能交付即構成違約。"}]', 'prepositional phrase'),
('on good terms', '關係良好；和睦相處', 'having a positive relationship with someone', '[{"en":"Despite the dispute we remain on good terms.","zh-TW":"儘管有爭議我們仍然保持良好關係。"},{"en":"She left the company on good terms with everyone.","zh-TW":"她離職時與每個人都保持良好關係。"}]', 'prepositional phrase'),
('at a discount', '以折扣價；打折', 'at a lower price than usual or standard', '[{"en":"The product is offered at a discount for bulk orders.","zh-TW":"大批量訂單提供折扣價。"},{"en":"They acquired the assets at a steep discount.","zh-TW":"他們以大幅折扣收購了這些資產。"}]', 'prepositional phrase'),
('in the spotlight', '在公眾目光下；受到關注', 'receiving a lot of public or media attention', '[{"en":"The CEO has been in the spotlight since the announcement.","zh-TW":"執行長自公告以來一直處於公眾目光下。"},{"en":"In the spotlight every decision is scrutinized.","zh-TW":"在受到關注的情況下每個決定都受到審視。"}]', 'prepositional phrase'),
('ahead of the pack', '領先群雄；走在前面', 'more advanced than one''s competitors', '[{"en":"Continuous investment keeps us ahead of the pack.","zh-TW":"持續投資讓我們領先群雄。"},{"en":"She ran ahead of the pack in the talent acquisition race.","zh-TW":"她在人才獲取競賽中走在前面。"}]', 'prepositional phrase'),
('in hot demand', '需求旺盛；炙手可熱', 'wanted by many people; very popular or sought-after', '[{"en":"Data scientists are in hot demand across all industries.","zh-TW":"數據科學家在所有行業都炙手可熱。"},{"en":"The product was in hot demand after the media coverage.","zh-TW":"媒體報導後該產品需求旺盛。"}]', 'prepositional phrase'),
('at a pace', '以某種速度；按某種節奏', 'at a particular speed or rate', '[{"en":"The business is growing at an impressive pace.","zh-TW":"業務以驚人的速度增長。"},{"en":"We are implementing changes at a manageable pace.","zh-TW":"我們以可控的節奏實施變革。"}]', 'prepositional phrase'),
('under scrutiny', '受到審查；接受仔細檢查', 'being carefully examined or investigated', '[{"en":"The firm''s accounting practices are under scrutiny.","zh-TW":"公司的會計做法正受到審查。"},{"en":"Under scrutiny all decisions must be justifiable.","zh-TW":"在受到審查的情況下所有決定都必須合理。"}]', 'prepositional phrase'),
('in a position to', '能夠；有條件去', 'having the ability or means to do something', '[{"en":"We are in a position to offer a better deal now.","zh-TW":"我們現在有條件提供更好的交易。"},{"en":"Are you in a position to commit by Friday?","zh-TW":"你能在週五前做出承諾嗎？"}]', 'prepositional phrase'),
('under the microscope', '受到嚴密審視；被仔細調查', 'being examined very carefully for problems', '[{"en":"After the recall every process was put under the microscope.","zh-TW":"召回後每個流程都受到嚴密審視。"},{"en":"The regulator put their practices under the microscope.","zh-TW":"監管機構對他們的做法進行了嚴密調查。"}]', 'prepositional phrase'),
('in the same boat', '同舟共濟；處境相同', 'in the same difficult situation as others', '[{"en":"We are all in the same boat with rising energy costs.","zh-TW":"面對不斷上漲的能源成本我們都同舟共濟。"},{"en":"The whole industry is in the same boat this year.","zh-TW":"今年整個行業處境相同。"}]', 'prepositional phrase'),
('from all angles', '從各個角度；全方位地', 'considering every perspective or approach', '[{"en":"We analyzed the proposal from all angles before deciding.","zh-TW":"我們在做決定前從各個角度分析了提案。"},{"en":"View the risk from all angles to ensure thorough assessment.","zh-TW":"從各個角度看待風險以確保全面評估。"}]', 'prepositional phrase'),
('have the edge over', '勝人一籌；比…略佔優勢', 'to have a slight advantage over a competitor', '[{"en":"Our after-sales service gives us the edge over rivals.","zh-TW":"我們的售後服務讓我們勝競爭對手一籌。"},{"en":"They have the edge over us in brand recognition.","zh-TW":"他們在品牌認知度方面略佔優勢。"}]', 'business idiom');